<?php
namespace App\Http\Controllers;
use App\Models\{User,Project,ProjectAttachment};use App\Services\{Operations,PrivateFiles};use App\Http\Requests\ProjectRequest;use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Gate};use Illuminate\Support\Str;
class ProjectController extends Controller {
 public function importLegacy(ProjectRequest $r){$r->validate(['id'=>'required|uuid']);$data=$r->validated();$project=Project::find($r->id);abort_if($project&&$project->owner_id!==$r->user()->id,404);if(!$project){$project=Project::create(['id'=>$r->id,'owner_id'=>$r->user()->id,'title'=>$data['title'],'description'=>$data['description'],'status'=>'New Request','types'=>$data['types']??[],'budget'=>$data['budget']??null,'timeline'=>$data['timeline']??null,'goal'=>$data['goal']??null,'target_users'=>$data['target_users']??null,'notes'=>$data['notes']??null,'details'=>['features'=>$data['features']??[],'customFeatures'=>$data['customFeatures']??[]]]);Operations::log($r->user(),'project.created','project',$project->id,['title'=>$project->title,'status'=>$project->status]);Operations::notify('project.created','project',$project->id,$project);}return $this->resource($project,true);}
 public function index(Request $r){$q=Operations::projectScope(Project::with(['owner:id,name,email','assignee:id,name']),$r->user());if($r->filled('search')){$search=mb_substr($r->search,0,140);$q->where(fn($q)=>$q->where('title','like','%'.$search.'%')->orWhereHas('owner',fn($u)=>$u->where('name','like','%'.$search.'%')));}if($r->filled('status'))$q->where('status',$r->status);$sort=in_array($r->query('sort'),['title','status','created_at'])?$r->query('sort'):'created_at';$page=$q->orderBy($sort,$r->query('direction')==='asc'?'asc':'desc')->paginate(min(100,max(10,(int)$r->query('per_page',20))));$page->getCollection()->transform(fn($p)=>$this->resource($p,$r->user()->role==='client'));return $page;}
 public function store(ProjectRequest $r,PrivateFiles $files){$data=$r->validated();$owner=$r->user()->role==='client'?$r->user():User::where('role','client')->where('status','active')->findOrFail($data['owner_id']);if($r->user()->role!=='client')abort_unless($r->user()->isManager(),403);$assignee=$data['assigned_to']??null;if($assignee)User::where('role','!=','client')->where('status','active')->findOrFail($assignee);
  $createdFiles=[];try{$project=DB::transaction(function()use($r,$data,$owner,$assignee,$files,&$createdFiles){$project=Project::create(['owner_id'=>$owner->id,'title'=>$data['title'],'description'=>$data['description'],'status'=>'New Request','assigned_to'=>$r->user()->role==='client'?null:$assignee,'types'=>$data['types']??[],'budget'=>$data['budget']??null,'timeline'=>$data['timeline']??null,'goal'=>$data['goal']??null,'target_users'=>$data['target_users']??null,'notes'=>$data['notes']??null,'details'=>['features'=>$data['features']??[],'customFeatures'=>$data['customFeatures']??[]]]);foreach($r->file('files',[]) as $file)$createdFiles[]=$files->store($file,$project,$r->user(),true);Operations::log($r->user(),'project.created','project',$project->id,['title'=>$project->title,'status'=>$project->status]);return $project;});}catch(\Throwable $error){foreach($createdFiles as $file)\Illuminate\Support\Facades\Storage::disk('local')->delete($file->path);throw $error;}
  Operations::notify('project.created','project',$project->id,$project);return response()->json($this->resource($project,$r->user()->role==='client'),201);}
 public function show(Request $r,Project $project){Gate::authorize('view',$project);$client=$r->user()->role==='client';$result=$this->resource($project->load(['owner:id,name,email,company,phone','assignee:id,name']),$client);$attachments=ProjectAttachment::where('project_id',$project->id);if($client)$attachments->where('client_visible',true);$result['files']=$attachments->latest()->get();$milestones=DB::table('project_milestones')->where('project_id',$project->id);if($client)$milestones->where('client_visible',true);$result['milestones']=$milestones->orderBy('due_date')->get();$result['conversations']=DB::table('conversations')->where('project_id',$project->id)->select('id','title','status')->get();$activity=DB::table('activity_logs')->leftJoin('users','users.id','=','activity_logs.actor_id')->where('target_type','project')->where('target_id',$project->id);if($client)$activity->whereIn('action',['project.created','project.updated','milestone.completed']);$result['activity']=$activity->orderByDesc('activity_logs.id')->limit(50)->get(['activity_logs.id','action','changes','activity_logs.created_at','users.name as actor']);if(!$client)$result['internal_notes']=DB::table('admin_notes')->join('users','users.id','=','admin_notes.author_id')->where('resource_type','project')->where('resource_id',$project->id)->latest('admin_notes.created_at')->get(['admin_notes.id','body','admin_notes.created_at','users.name as author']);return $result;}
 public function update(ProjectRequest $r,Project $project){Gate::authorize('update',$project);$data=$r->validated();unset($data['owner_id'],$data['files'],$data['features'],$data['customFeatures']);if(!$r->user()->isManager())unset($data['assigned_to']);if(!empty($data['assigned_to']))User::where('role','!=','client')->where('status','active')->findOrFail($data['assigned_to']);DB::transaction(function()use($r,$project,$data){$locked=Project::lockForUpdate()->findOrFail($project->id);abort_unless($locked->version===$data['version'],409,'This project changed. Refresh before saving.');unset($data['version']);$before=$locked->only(['status','assigned_to']);$locked->fill($data);$changes=$locked->getDirty();$locked->version++;$locked->save();Operations::log($r->user(),'project.updated','project',$project->id,array_intersect_key($changes,array_flip(['title','status','assigned_to','budget','timeline'])));if(isset($changes['assigned_to'])){DB::table('conversations')->where('project_id',$project->id)->update(['assigned_to'=>$locked->assigned_to,'updated_at'=>now()]);}});$project->refresh();Operations::notify('project.updated','project',$project->id,$project);return $this->resource($project);}
 public function milestone(Request $r,Project $project){Gate::authorize('update',$project);$data=$r->validate(['id'=>'sometimes|uuid','title'=>'required|string|max:180','due_date'=>'nullable|date','completed'=>'required|boolean','client_visible'=>'required|boolean']);$mid=$data['id']??Str::uuid()->toString();unset($data['id']);if($r->filled('id'))abort_unless(DB::table('project_milestones')->where('id',$mid)->where('project_id',$project->id)->exists(),404);DB::table('project_milestones')->updateOrInsert(['id'=>$mid,'project_id'=>$project->id],$data+['updated_at'=>now(),'created_at'=>now()]);Operations::log($r->user(),$data['completed']?'milestone.completed':'milestone.updated','project',$project->id,['milestone_id'=>$mid]);return ['ok'=>true];}
 public function note(Request $r,Project $project){Gate::authorize('update',$project);$data=$r->validate(['body'=>'required|string|max:5000']);DB::table('admin_notes')->insert(['id'=>Str::uuid()->toString(),'resource_type'=>'project','resource_id'=>$project->id,'author_id'=>$r->user()->id,'body'=>$data['body'],'created_at'=>now(),'updated_at'=>now()]);Operations::log($r->user(),'note.added','project',$project->id);return ['ok'=>true];}
 public function discuss(Request $r,Project $project){Gate::authorize('view',$project);abort_unless($r->user()->role==='client'||$r->user()->allows('messages'),403);$conversation=DB::table('conversations')->where('project_id',$project->id)->first();if(!$conversation){$cid=Str::uuid()->toString();DB::transaction(function()use($project,$cid){DB::table('conversations')->insert(['id'=>$cid,'title'=>$project->title,'project_id'=>$project->id,'client_id'=>$project->owner_id,'assigned_to'=>$project->assigned_to,'status'=>'open','created_at'=>now(),'updated_at'=>now()]);DB::table('conversation_participants')->insert(['conversation_id'=>$cid,'user_id'=>$project->owner_id,'last_read_message_id'=>0,'muted'=>0]);});$conversation=DB::table('conversations')->where('id',$cid)->first();}return ['conversation_id'=>$conversation->id];}
 private function resource(Project $p,bool $client=false):array{$value=$p->toArray();$value['status']=Operations::status($p->status);$value['createdAt']=$p->created_at?->toISOString();$value['updatedAt']=($p->updated_at??$p->created_at)?->toISOString();$value['targetUsers']=$p->target_users;$value['features']=$p->details['features']??[];$value['customFeatures']=$p->details['customFeatures']??[];$value['files']=ProjectAttachment::where('project_id',$p->id)->when($client,fn($q)=>$q->where('client_visible',true))->get()->map(fn($a)=>['id'=>$a->id,'name'=>$a->name,'size'=>$a->size,'type'=>$a->mime_type]);$value['activity']=[['text'=>$value['status'],'time'=>$value['updatedAt']]];return $value;}
}
